<template>
  <view class="container">
    <!-- 上层分类区域 - 动态生成 -->
    <view class="top-control">
      <button 
        v-for="(category, index) in categoryList" 
        :key="category.id || index"
        @click="refreshData(category.id)"
        :class="['top-btn', { 'active': currentCategory === category.id }]"
      >
        {{ category.name }}
      </button>
    </view>
    
    <!-- 横向滚动容器 -->
    <scroll-view 
      scroll-x="true" 
      :scroll-left="scrollLeft" 
      scroll-with-animation
      class="scroll-view-content"
      @scroll="onScroll"
    >
      <view 
        class="scroll-item" 
        v-for="(item, index) in itemList" 
        :key="item.id"
        :class="{ 'active': currentIndex === index }"
        @click="handleItemClick(index)"
        :id="'item-' + index"
      >
        <text>{{ item.title }}</text>
      </view>
    </scroll-view>
    
    <!-- 加载状态 -->
    <view v-if="loading" class="loading-container">
      <text class="loading-text">加载中...</text>
    </view>
    
    <!-- 控制按钮区域 -->
    <view class="control-panel">
      <button @click="scrollToIndex(0)" class="control-btn">滚动到第一个</button>
      <button @click="scrollToIndex(2)" class="control-btn">滚动到第三个</button>
      <button @click="scrollToIndex(itemList.length - 1)" class="control-btn">滚动到最后一个</button>
    </view>
  </view>
</template>

<script>
export default {
  data() {
    return {
      scrollLeft: 0,
      currentIndex: 0,
      currentCategory: '', // 当前选中的分类ID
      contentScrollW: 0,
      itemWidths: [],
      itemList: [],
      categoryList: [], // 存储分类数据
      loading: false,
      error: null
    }
  },
  
  onLoad(options) {
    // 页面加载时获取分类数据
    this.fetchCategories().then(() => {
      // 如果有URL参数指定分类，则使用指定分类，否则使用第一个分类
      if (options.category) {
        this.refreshData(options.category)
      } else if (this.categoryList.length > 0) {
        this.refreshData(this.categoryList[0].id)
      }
    })
    
    // 支持通过URL参数传递初始索引
    if (options.index) {
      const initialIndex = parseInt(options.index)
      this.$nextTick(() => {
        setTimeout(() => {
          this.scrollToIndex(initialIndex)
        }, 500)
      })
    }
  },
  
  methods: {
    // 获取分类列表数据
    async fetchCategories() {
      try {
        this.loading = true
        this.error = null
        
        // 模拟API调用获取分类数据
        const mockCategories = await this.mockApiCall('categories', [
          { id: 'category1', name: '热门推荐', type: 'hot' },
          { id: 'category2', name: '新品上市', type: 'new' },
          { id: 'category3', name: '特价优惠', type: 'discount' },
          { id: 'category4', name: '精选商品', type: 'featured' },
          { id: 'category5', name: '限时抢购', type: 'flash' }
        ])
        
        this.categoryList = mockCategories
        return mockCategories
        
      } catch (error) {
        console.error('获取分类数据失败:', error)
        this.error = '分类数据加载失败'
        uni.showToast({ title: '分类数据加载失败', icon: 'none' })
        throw error
      } finally {
        this.loading = false
      }
    },
    
    // 获取指定分类下的项目数据
    async fetchItemsByCategory(categoryId) {
      try {
        this.loading = true
        this.error = null
        
        // 模拟不同分类返回不同数据
        const categoryDataMap = {
          category1: [
            { id: 1, title: '热门商品1', price: '¥199' },
            { id: 2, title: '热门商品2', price: '¥299' },
            { id: 3, title: '热门商品3', price: '¥399' },
            { id: 4, title: '热门商品4', price: '¥499' },
            { id: 5, title: '热门商品5', price: '¥599' }
          ],
          category2: [
            { id: 6, title: '新品首发1', price: '¥159' },
            { id: 7, title: '新品首发2', price: '¥259' },
            { id: 8, title: '新品首发3', price: '¥359' },
            { id: 9, title: '新品首发4', price: '¥459' },
            { id: 10, title: '新品首发5', price: '¥559' },
            { id: 11, title: '新品首发6', price: '¥659' },
            { id: 12, title: '新品首发7', price: '¥759' }
          ],
          category3: [
            { id: 13, title: '特价商品1', price: '¥99' },
            { id: 14, title: '特价商品2', price: '¥129' },
            { id: 15, title: '特价商品3', price: '¥159' },
            { id: 16, title: '特价商品4', price: '¥189' },
            { id: 17, title: '特价商品5', price: '¥219' }
          ],
          category4: [
            { id: 18, title: '精选商品1', price: '¥199' },
            { id: 19, title: '精选商品2', price: '¥299' },
            { id: 20, title: '精选商品3', price: '¥399' },
            { id: 21, title: '精选商品4', price: '¥499' },
            { id: 22, title: '精选商品5', price: '¥599' },
            { id: 23, title: '精选商品6', price: '¥699' },
            { id: 24, title: '精选商品7', price: '¥799' },
            { id: 25, title: '精选商品8', price: '¥899' }
          ],
          category5: [
            { id: 26, title: '限时秒杀1', price: '¥59' },
            { id: 27, title: '限时秒杀2', price: '¥79' },
            { id: 28, title: '限时秒杀3', price: '¥99' },
            { id: 29, title: '限时秒杀4', price: '¥119' },
            { id: 30, title: '限时秒杀5', price: '¥139' }
          ]
        }
        
        const mockItems = await this.mockApiCall(`items/${categoryId}`, categoryDataMap[categoryId] || [])
        return mockItems
        
      } catch (error) {
        console.error(`获取分类 ${categoryId} 数据失败:`, error)
        this.error = '商品数据加载失败'
        uni.showToast({ title: '商品数据加载失败', icon: 'none' })
        throw error
      } finally {
        this.loading = false
      }
    },
    
    // 模拟API调用
    mockApiCall(endpoint, data, delay = 500) {
      return new Promise((resolve, reject) => {
        setTimeout(() => {
          // 模拟10%的失败率
          if (Math.random() < 0.1) {
            reject(new Error(`API调用失败: ${endpoint}`))
          } else {
            resolve(data)
          }
        }, delay)
      })
    },
    
    // 刷新数据方法
    async refreshData(categoryId) {
      try {
        this.currentCategory = categoryId
        
        // 显示加载状态
        uni.showLoading({ title: '加载中...' })
        
        // 获取该分类下的项目数据
        const items = await this.fetchItemsByCategory(categoryId)
        this.itemList = items
        
        // 重置状态
        this.currentIndex = 0
        this.scrollLeft = 0
        this.itemWidths = []
        
        // 等待DOM更新后重新获取尺寸信息
        await this.$nextTick()
        await this.getScrollElementInfo()
        
        // 可选：滚动到第一个位置
        setTimeout(() => {
          this.scrollToIndex(0)
        }, 100)
        
        uni.hideLoading()
        
      } catch (error) {
        console.error('数据加载失败:', error)
        uni.hideLoading()
        uni.showToast({ title: '加载失败', icon: 'none' })
      }
    },
    
    // 获取滚动元素尺寸
    getScrollElementInfo() {
      return new Promise((resolve) => {
        this.$nextTick(() => {
          const query = uni.createSelectorQuery().in(this)
          
          query.select('.scroll-view-content').boundingClientRect(container => {
            if (!container) {
              console.error('未找到滚动容器')
              resolve()
              return
            }
            this.contentScrollW = container.width

            query.selectAll('.scroll-item').boundingClientRect(items => {
              if (!items || items.length === 0) {
                console.error('未找到轮次项')
                resolve()
                return
              }
              this.itemWidths = items.map(item => item.width + 20)
              resolve()
            }).exec()
          }).exec()
        })
      })
    },
    
    // 处理子项点击事件
    async handleItemClick(index) {
      this.currentIndex = index
      await this.$nextTick()
      this.calculateScrollPosition(index)
    },
    
    // 滚动到指定索引位置
    async scrollToIndex(index) {
      if (index < 0 || index >= this.itemList.length) {
        console.warn('索引超出范围')
        return
      }
      
      this.currentIndex = index
      await this.$nextTick()
      
      if (this.itemWidths.length === 0 || this.contentScrollW === 0) {
        await this.getScrollElementInfo()
      }
      
      this.calculateScrollPosition(index)
    },
    
    // 计算滚动位置
    calculateScrollPosition(index) {
      if (this.itemWidths.length === 0 || this.contentScrollW === 0) {
        console.error('滚动参数异常')
        return
      }

      let totalWidthBefore = 0
      for (let i = 0; i < index; i++) {
        totalWidthBefore += this.itemWidths[i]
      }

      const currentItemWidth = this.itemWidths[index] || 0
      const halfContainer = Math.max(1, this.contentScrollW / 2)
      const halfItem = currentItemWidth / 2
      let targetScrollLeft = totalWidthBefore - halfContainer + halfItem

      targetScrollLeft = Math.max(0, targetScrollLeft)
      const query = uni.createSelectorQuery().in(this)
      query.select('.scroll-view-content').boundingClientRect((rect) => {
        if (rect) {
          const scrollContentWidth = rect.width
          targetScrollLeft = Math.min(targetScrollLeft, scrollContentWidth - this.contentScrollW)
          this.scrollLeft = targetScrollLeft
        }
      }).exec()
    },
    
    // 滚动事件监听
    onScroll(e) {
      // 可根据需要处理滚动过程中的逻辑
      console.log('当前滚动位置:', e.detail.scrollLeft)
    }
  }
}
</script>

<style scoped>
.container {
  padding: 30rpx;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
}

.top-control {
  margin-bottom: 30rpx;
  display: flex;
  flex-wrap: wrap;
  gap: 20rpx;
  justify-content: center;
}

.top-btn {
  background: rgba(255, 255, 255, 0.2);
  color: white;
  border: 1rpx solid rgba(255, 255, 255, 0.3);
  border-radius: 20rpx;
  padding: 15rpx 25rpx;
  font-size: 28rpx;
  transition: all 0.3s ease;
}

.top-btn.active {
  background: rgba(255, 255, 255, 0.4);
  font-weight: bold;
  transform: scale(1.05);
}

.scroll-view-content {
  width: 100%;
  height: 100rpx;
  white-space: nowrap;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 50rpx;
  padding: 0 20rpx;
  box-shadow: 0 8rpx 32rpx rgba(0, 0, 0, 0.1);
  backdrop-filter: blur(10rpx);
  border: 1rpx solid rgba(255, 255, 255, 0.2);
}

.scroll-item {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 70rpx;
  padding: 0 30rpx;
  margin: 15rpx 10rpx;
  background: rgba(255, 255, 255, 0.15);
  border-radius: 35rpx;
  color: white;
  font-size: 28rpx;
  transition: all 0.3s ease;
}

.scroll-item.active {
  background: rgba(255, 255, 255, 0.3);
  font-weight: bold;
  transform: scale(1.05);
}

.loading-container {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20rpx;
}

.loading-text {
  color: white;
  font-size: 28rpx;
}

.control-panel {
  margin-top: 40rpx;
  display: flex;
  flex-wrap: wrap;
  gap: 20rpx;
  justify-content: center;
}

.control-btn {
  background: rgba(255, 255, 255, 0.25);
  color: white;
  border: none;
  border-radius: 20rpx;
  padding: 15rpx 25rpx;
  font-size: 26rpx;
  transition: all 0.3s ease;
}

.control-btn:active {
  background: rgba(255, 255, 255, 0.4);
  transform: scale(0.95);
}
</style>